def is_prime(n):
    if n < 2:
        return False
    # Check small primes first
    small_primes = [2,3,5,7,11,13,17,19,23]
    for sp in small_primes:
        if n == sp:
            return True
        if n % sp == 0 and n != sp:
            return False

    # Miller-Rabin primality test
    def miller_rabin_test(d, n, a):
        x = pow(a, d, n)
        if x == 1 or x == n -1:
            return True
        while d != n -1:
            x = (x * x) % n
            d *= 2
            if x == 1:
                return False
            if x == n -1:
                return True
        return False

    # find d such that n-1 = d * 2^r
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    # Test with few bases for accuracy up to 2*10^9
    test_bases = [2, 3, 5, 7, 11]
    for a in test_bases:
        if a > n - 2:
            break
        if not miller_rabin_test(d, n, a):
            return False
    return True

n = int(input())

if is_prime(n):
