x, y = map(int, input().split())

def solve(x, y):
    # impossible if both are equal and >1 or less than 1
    if x <=0 or y <=0:
        return "Impossible"
    if x == 1 and y == 1:
        return ""  # no cards needed

    seq = []
    while True:
        if x == 1 and y ==1:
            break
        if x == y:
            return "Impossible"
        if x > y:
            k = x // y
            if k == 0:
                return "Impossible"
            # if by subtracting k * y we get less than 1, impossible
            if x - k * y <=0:
                k -=1
            if k ==0:
                return "Impossible"
            seq.append(('A', k))
            x = x - k * y
        else:  # y > x
            k = y // x
            if k == 0:
                return "Impossible"
            if y - k * x <=0:
                k -=1
            if k ==0:
                return "Impossible"
            seq.append(('B', k))
            y = y - k * x

    # reverse the sequence because we constructed it backwards
    seq.reverse()

    # compress and print
    res = []
    for letter, count in seq:
        res.append(str(count))
        res.append(letter)
    return "".join(res)

print(solve(x,y))

