    while b:
        a, b = b, a % b
    return a

def solve(x, y, a, b):
    ans = []
    while x != 1 or y != 1:
        if x < y:
            x, y = y, x
            a, b = b, a
        q = (x - 1) // y
        ans.append(q * a)
        x -= q * y

    # Now compress the string
    s = "".join(ans)
    res = []
    count = 1
    for i in range(1, len(s) + 1):
        if i < len(s) and s[i] == s[i-1]:
            count += 1
        else:
            res.append(str(count) + s[i-1])
            count = 1
    print("".join(res))

