def fill_interval(l, r):
    if l == r:
        return 0

    if a[l] == a[r]:
        for i in range(l+1, r):
            a[i] = a[l]
        return (r - l) // 2
    else:
        m = (l + r + 1) // 2
        for i in range(l+1, m):
            a[i] = a[l]
        for i in range(m, r):
            a[i] = a[r]
        return (r - l - 1) // 2

