def solver(L, k):
    n = len(L)
    if k >= n:
        return L[-1]
    else:
        maximum = L[-1]
        pack2s = L[:2*(n - k)]
        for i in range(n - k):
            size = pack2s[i] + pack2s[-i-1]
            if size > maximum:
                maximum = size
