from operator import mul
import math


def prod(iterable, start=1):
    return reduce(mul, iterable, start)


def relevant_factors(n):
    for i in range(2, 2000000):
        if i ** 2 > n:
            break
        c = 0
        q, r = divmod(n, i)
        while r == 0:
            c += 1
            n = q
            q, r = divmod(n, i)
        if c:
            yield (i, c)

    if n > 1:
        sn = math.isqrt(n)
        if sn * sn == n:
            yield (sn, 2)
        elif sn * (sn + 1) == n:
            yield (sn, 1)
            yield (sn + 1, 1)
        else:
            yield (n, 1)


def divisors(factors):
    def powers(base, exponent):
        k = 1
        for _ in range(exponent):
            yield k
            k *= base

    from itertools import product
    return sorted(prod(t) for t in product(*[powers(f, e + 1) for f, e in factors]))


