def grundy(k, pile_size):
    # Precompute known values for small piles
    G_EVEN = {0: 0, 1: 1, 2: 2}
    G_ODD = {0: 0, 1: 1, 2: 0, 3: 1}

    if k % 2 == 1:  # k is odd
        if pile_size <= 3:
            return G_ODD[pile_size]
        if pile_size % 2 == 1:
            # Odd pile sizes greater than 3 have grundy number 0 for k odd
            return 0
        # pile_size is even, factor out powers of two
        power = 0
        remainder = pile_size
        while remainder % 2 == 0:
            remainder >>= 1
            power += 1
        # remainder is now odd
        if remainder == 3:
            # When remainder is 3, grundy depends on parity of power
            return 2 if power % 2 == 1 else 1
        else:
            # For odd remainder != 3, grundy depends on parity of power
            return 1 if power % 2 == 1 else 2

    else:  # k is even
        if pile_size <= 2:
            return G_EVEN[pile_size]
        # For larger piles, grundy depends on parity of pile_size
        return (~pile_size) & 1


def nim_sum(grundy_values):
    result = 0
    for g in grundy_values:
        result ^= g
    return result


def winner(k, piles):
    grundy_vals = (grundy(k, pile) for pile in piles)
    return nim_sum(grundy_vals) != 0


if __name__ == '__main__':
    n, k = map(int, input().split())
    piles = list(map(int, input().split()))
    print("Kevin" if winner(k, piles) else "Nicky")

