def graph(edges):
    edges = [(w, i, b) for i, (w, b) in enumerate(edges)]
    edges.sort(key=lambda x: x[0])

    g = [None] * len(edges)

    mst = [(w, i) for w, i, b in edges if b == 1]
    # Assign MST edges as (1, 2), (1, 3), ..., (1, n)
    for idx, (w, i) in enumerate(mst, 2):
        g[i] = (1, idx)

    cm = 0
    available = []

    for w, i, b in edges:
        if b == 0:
            if not available:
                cm += 1
                # If weight of MST edge at cm is greater than current weight, no solution
                if cm >= len(mst) or mst[cm][0] > w:
                    return None
                # Generate new available pairs for the next group of edges
                available = [(u, cm + 2) for u in range(2, cm + 2)]
            g[i] = available.pop()

    return g


if __name__ == '__main__':
    n, m = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]
    g = graph(edges)
    if g is not None:
        for u, v in g:
            print(u, v)
    else:
        print(-1)

