for num in tanks:
    if num == '0':
        # product will be zero regardless
        zero_found = True
    if is_beautiful(num):
        # Count zeros after the single '1' if exists
        # If number is '0', zeros count as zero anyway (since it's zero)
        if num != '0':
            # number has at most one '1'
            # find position of '1' and count zeros after it
            one_pos = num.find('1')
            zeros_after = len(num) - one_pos - 1
            total_zeros += zeros_after
    else:
        # Should be only one such number
        if non_beautiful_num is None:
            non_beautiful_num = num
        else:
            # Problem guarantees only one non-beautiful number
            # But if more appear, just keep the first
