    n, m = map(int, input().split())
    adj = [[] for _ in range(n)]

    for _ in range(m):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    ans = ["c"] * n
    visited = [0] * n

    # Assign 'b' to vertices with degree n-1 (fully connected)
    for i in range(n):
        if len(adj[i]) == n - 1:
            visited[i] = 1
            ans[i] = "b"

    def dfs(s, c):
        stack = [s]
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = 1
            ans[node] = c
            for nei in adj[node]:
                if not visited[nei]:
                    stack.append(nei)

    # For remaining not visited nodes (ans[i] == 'c'), assign 'a' to one connected component
    if "c" in ans:
        st = ans.index("c")
        dfs(st, "a")

    # If still some 'c' remain, assign 'c' to that connected component
    if "c" in ans:
        st = ans.index("c")
        dfs(st, "c")

    cnta = ans.count("a")
    cntb = ans.count("b")
    cntc = ans.count("c")

