import math
from itertools import combinations

def lcm(a, b):
    return a * b // math.gcd(a, b)

def lcm_multiple(numbers):
    current_lcm = 1
    for num in numbers:
        current_lcm = lcm(current_lcm, num)
        if current_lcm > 10**18:
            # No need to go beyond n since counts will be zero for larger lcm
            break
    return current_lcm

def main():
    n = int(input())
    divisors = [2,3,4,5,6,7,8,9,10]

    total_divisible = 0

    # Inclusion-Exclusion principle
    for r in range(1, len(divisors)+1):
        for combo in combinations(divisors, r):
            l = lcm_multiple(combo)
            if l > n:
                continue
            count = n // l
            if r % 2 == 1:
                total_divisible += count
            else:
                total_divisible -= count

    result = n - total_divisible
    print(result)

if __name__ == "__main__":
