def solver(ps, s):
    initial_score = 0
    delta = []
    for i in range(len(s)):
        if s[i] == 'B':
            initial_score += ps[i]
            delta.append(-ps[i])
        else:  # s[i] == 'A'
            delta.append(ps[i])

    best_delta = 0
    # max prefix sum
    current = 0
    for x in delta:
        current += x
        if current > best_delta:
            best_delta = current
        if current < 0:
            current = 0

    # max suffix sum
    current = 0
    for x in reversed(delta):
        current += x
        if current > best_delta:
            best_delta = current
        if current < 0:
            current = 0

    return initial_score + best_delta

