def trailing_zeros(n):
    count = 0
    divisor = 5
    while divisor <= n:
        count += n // divisor
        divisor *= 5
    return count

def binary_search_left(m):
    low, high = 1, 5 * (m + 1) * 10  # safe upper bound
    res = -1
    while low <= high:
        mid = (low + high) // 2
        tz = trailing_zeros(mid)
        if tz == m:
            res = mid
            high = mid - 1  # continue searching left for minimal n
        elif tz < m:
            low = mid + 1
        else:
