def ziped(blocks):
    merged = []
    for block in blocks:
        length_str, char = block.split('-')
        length = int(length_str)
        if merged and merged[-1][1] == char:
            merged[-1][0] += length
        else:
            merged.append([length, char])
    return merged

def solve(t_blocks, s_blocks, match):
    ans = 0
    if len(s_blocks) == 1:
        target_len, target_char = s_blocks[0]
        for length, char in t_blocks:
            if match((length, char), (target_len, target_char)):
                ans += length - target_len + 1
        return ans

    if len(s_blocks) == 2:
        s1, s2 = s_blocks[0], s_blocks[1]
        for i in range(len(t_blocks) - 1):
            if match(t_blocks[i], s1) and match(t_blocks[i + 1], s2):
                ans += 1
        return ans

    # For len(s_blocks) >= 3: KMP on middle blocks
    middle = s_blocks[1:-1]
    sentinel = [100500, '#']
    v = middle + [sentinel] + t_blocks

    prefix = [0] * len(v)
    for i in range(1, len(v)):
        j = prefix[i - 1]
        while j > 0 and v[i] != v[j]:
            j = prefix[j - 1]
        if v[i] == v[j]:
            j += 1
        prefix[i] = j

    left_block = s_blocks[0]
    right_block = s_blocks[-1]
    m = len(middle)
    for i in range(m, len(v) - 1):
        if prefix[i] == m:
            start = i - 2 * m
            # Check left and right blocks
            if start >= 0 and match(v[start], left_block) and match(v[i + 1], right_block):
                ans += 1

    return ans

