def main():
    from bisect import bisect_left
    n, k = map(int, input().split())
    s = input()
    zeros = [i for i, c in enumerate(s) if c == '0']
    res = n  # Initialize with max value

    for i in range(len(zeros) - k):
        j = i + k
        left, right = zeros[i], zeros[j]
        mid_val = (left + right) // 2

        pos = bisect_left(zeros, mid_val)

        candidates = []
        if pos < len(zeros):
            candidates.append(zeros[pos])
        if pos > 0:
            candidates.append(zeros[pos - 1])

        best = n
        for c in candidates:
            dist = max(c - left, right - c)
            if dist < best:
                best = dist

        if best < res:
            res = best

    print(res)


if __name__ == '__main__':
    main()

