def is_violation(t, i):
    # Check if position i violates nice condition; i is 1-based
    if i < 1 or i >= len(t):
        return False
    if i % 2 == 1:
        return t[i - 1] >= t[i]
    else:
        return t[i - 1] <= t[i]

def check_positions(t, positions):
    # Check if sequence t is nice at given positions (and their neighbors)
    n = len(t)
    for pos in positions:
        if 1 <= pos < n:
            if is_violation(t, pos):
                return False
    return True

def main():
    import sys
    input = sys.stdin.readline

    n = int(input())
    t = list(map(int, input().split()))

    violations = []
    for i in range(1, n):
        if is_violation(t, i):
            violations.append(i)
    # If there are too many violations, no one-swap fix possible
    if len(violations) > 10:
        print(0)
        return

    candidate_indices = set()
    for v in violations:
        # indices involved in violation v: v and v+1
        candidate_indices.add(v)
        candidate_indices.add(v + 1)
        if v - 1 >= 1:
            candidate_indices.add(v - 1)
        if v + 2 <= n:
            candidate_indices.add(v + 2)
    candidate_indices = [i for i in candidate_indices if 1 <= i <= n]

    candidate_indices.sort()

    ans = 0
    tried_pairs = set()
    for i in candidate_indices:
        for j in candidate_indices:
            if i < j and (i, j) not in tried_pairs:
                tried_pairs.add((i, j))

                t[i - 1], t[j - 1] = t[j - 1], t[i - 1]

                # Positions to check are around i and j
                positions_to_check = {i - 1, i, j - 1, j}

                if check_positions(t, positions_to_check):
                    ans += 1

                t[i - 1], t[j - 1] = t[j - 1], t[i - 1]

    print(ans)

if __name__ == "__main__":
    main()

