import sys
sys.setrecursionlimit(10**7)

s = input()
n = len(s)

# We will try all root lengths from 5 to n (root length > 4)
# For each root_len, try to parse suffix sequence s[root_len:]
# We want to find suffix sequences of length 2 or 3, with no two equal suffixes consecutively.

from functools import lru_cache

result_suffixes = set()

for root_len in range(5, n+1):
    suffix_seq = s[root_len:]
    length = len(suffix_seq)
    if length == 0:
        # no suffixes appended
        # skip since we want suffixes appended
        continue

    @lru_cache(None)
    def dp(pos, prev):
        if pos == length:
            return True
        # try suffixes of length 2 or 3 from pos
        for l in [2,3]:
            if pos + l <= length:
                curr = suffix_seq[pos:pos+l]
                if curr != prev:
                    if dp(pos+l, curr):
                        return True
        return False

    if not dp(0, ''):
        continue

    # Now, collect all suffixes used in any successful parsing.
    # We'll do a DFS collecting suffixes from dp.
    # Use memo with True/False, and try all possible suffixes.
    suffixes_in_this = set()
    visited = set()
    def dfs(pos, prev):
        if pos == length:
            return True
        if (pos, prev) in visited:
            return False
        visited.add((pos, prev))
        for l in [2,3]:
            if pos + l <= length:
                curr = suffix_seq[pos:pos+l]
                if curr != prev and dp(pos+l, curr):
                    suffixes_in_this.add(curr)
                    if dfs(pos+l, curr):
                        # keep searching to find all suffixes
                        pass
        return True
    dfs(0, '')

    result_suffixes.update(suffixes_in_this)

# Print result
res = sorted(result_suffixes)
print(len(res))
for suf in res:
    print(suf)

