from collections import deque

def argmax(que, z):
    # Binary search on deque to find the smallest 'i' in que with i > z
    l, r = 0, len(que) - 1
    while l <= r:
        mid = (l + r) // 2
        if que[mid]['i'] <= z:
            r = mid - 1
        else:
            l = mid + 1
    # After loop, l points to position with que[l]['i'] > z
    # Since l may be out of range, return que[l]['i'] safely
    # Due to problem constraints, l should be within range
    return que[l]['i']

def solve(n, A):
    a = [0] * (n + 1)
    a[1:] = A
    dp = [0] * (n + 1)
    dp[n - 1] = 1  # From station n-1 to n requires 1 ticket

    que = deque()
    que.append({'i': n - 1, 'a': a[n - 1]})

    for i in range(n - 2, 0, -1):
        if a[i] >= n:
            dp[i] = n - i
        else:
            x = argmax(que, a[i])
            dp[i] = (x - i) + dp[x] + (n - a[i])
        # Maintain deque in decreasing order of a[i]
        while que and que[-1]['a'] < a[i]:
            que.pop()
        que.append({'i': i, 'a': a[i]})
    return sum(dp)

if __name__ == '__main__':
    n = int(input())
    A = list(map(int, input().split()))
    print(solve(n, A))

