def to_decimal(digits):
    res = 0
    for d in digits:
        res = res * 7 + d
    return res

def base7_len(x):
    if x == 0:
        return 1
    length = 0
    while x > 0:
        x //=7
        length +=1
    return length

def main():
    n, m = map(int, input().split())

    h_len = base7_len(n - 1)
    m_len = base7_len(m - 1)

    # If total digits exceed 7, impossible to have all distinct digits
    if h_len + m_len > 7:
        print(0)
        return

    count = 0

    used = [False]*7  # to track digits usage

    # generate all possible hour digits
    def backtrack_hour(pos, h_digits):
        if pos == h_len:
            val = to_decimal(h_digits)
            if val >= n:
                return
            # mark used digits
            for d in h_digits:
                if used[d]:
                    return
            for d in h_digits:
                used[d] = True
            backtrack_minute(0, [])
            for d in h_digits:
                used[d] = False
            return

        for d in range(7):
            # no constraint on digit choice here, digits can be repeated in hour part
            # but must be checked globally with minute digits - that is done later.
            h_digits.append(d)
            backtrack_hour(pos+1, h_digits)
            h_digits.pop()

    def backtrack_minute(pos, m_digits):
        nonlocal count
        if pos == m_len:
            val = to_decimal(m_digits)
            if val >= m:
                return
            # Check if digits in m_digits are distinct and not used in hour digits
            for d in m_digits:
                if used[d]:
                    return
            for d in m_digits:
                if m_digits.count(d) > 1:
                    return
            count += 1
            return

        for d in range(7):
            m_digits.append(d)
            backtrack_minute(pos+1, m_digits)
            m_digits.pop()

    backtrack_hour(0, [])

    print(count)

if __name__ == "__main__":
    main()

