# Coordinates:
# Cells: rows from top to bottom y = N ... 1 (row 0 is y=N)
# columns from left to right x=1...N (col 0 is x=1)
# cell at (x,y) corresponds to grid[N - y][x - 1]

def valid_rectangle(x1, y1, x2, y2):
    # x1 < x2, y1 < y2
    if not (0 <= x1 < x2 <= N and 0 <= y1 < y2 <= N):
        return False
    return True

for x1 in range(N):
    for x2 in range(x1+1, N+1):
        for y1 in range(N):
            for y2 in range(y1+1, N+1):
                # Check rectangle (x1,y1,x2,y2)
                # For each cell (x,y), 1-based:
                # contamination = number of the 4 corners inside the rectangle:
                # corners: (x-1,y), (x,y), (x-1,y-1), (x,y-1)
                # We check if each corner is in rectangle:
                # x1 ≤ cx ≤ x2 and y1 ≤ cy ≤ y2

                # verify all cells:
                match = True
                for yi in range(N):
                    # y of the cell: N - yi (top row is y=N)
                    y = N - yi
                    for x in range(1, N+1):
                        count = 0
                        for cx, cy in [(x-1,y), (x,y), (x-1,y-1), (x,y-1)]:
                            if x1 <= cx <= x2 and y1 <= cy <= y2:
                                count += 1
                        if count != grid[yi][x-1]:
                            match = False
                            break
                    if not match:
                        break
                if match:
                    print("Yes")
                    exit(0)

