# Activities: 0 - rest, 1 - contest, 2 - sport
# dp[i][activity] = minimal rest days count up to day i where day i's activity is 'activity'
dp = [[float('inf')] * 3 for _ in range(n)]

# For day 0, set dp accordingly based on possible activities
for act in range(3):
    # Check if current activity is possible on day 0 based on a[0]
    can_contest = a[0] in [1, 3]
    can_sport = a[0] in [2, 3]
    if act == 0:
        # rest always possible
        dp[0][0] = 1
    elif act == 1 and can_contest:
        dp[0][1] = 0
    elif act == 2 and can_sport:
        dp[0][2] = 0

for i in range(1, n):
    can_contest = a[i] in [1, 3]
    can_sport = a[i] in [2, 3]
    for curr_act in range(3):
        # Check if curr_act is possible this day
        if curr_act == 0:
            # rest is always possible
            cost = 1
        elif curr_act == 1:
            if not can_contest:
                continue
            cost = 0
        elif curr_act == 2:
            if not can_sport:
                continue
            cost = 0

        for prev_act in range(3):
            # Can't do same activity two days in a row (except rest can follow rest or any activity)
            # But per problem rest (0) can be done any number of times, no restrictions.
            # The problem states Vasya refuses to do same activity on two consecutive days, including rest?
