import math

def get_cnt(res):
    # Using quadratic formula to find n s.t n*(n-1)/2 = res
    if res == 0:
        return 0
    n = int((1 + math.isqrt(1 + 8*res)) // 2)
    if n * (n - 1) // 2 == res:
        return n
    else:
        return -1

def calc():
    cnt = list(map(int, input().split()))
    a00, a01, a10, a11 = cnt
    if cnt == [0, 0, 0, 0]:
        return '0'

    a = get_cnt(a00)
    b = get_cnt(a11)

    # Handle the case when zero subsequences but others exist
    if a00 == 0 and a01 == 0 and a10 == 0 and a11 > 0:
        a = 0
    if a11 == 0 and a01 == 0 and a10 == 0 and a00 > 0:
        b = 0

    if a == -1 or b == -1:
        return "Impossible"

    # Check if total cross subsequences match
    if a * b != a01 + a10:
        return "Impossible"

    # Special cases when either zeros or ones are zero
    if a == 0:
        if a01 + a10 == 0:
            return '1' * b
        else:
            return "Impossible"
    if b == 0:
        if a01 + a10 == 0:
            return '0' * a
        else:
            return "Impossible"

    ans = ['0'] * (a + b)
    i = 0
    # Distribute ones in the string:
    # while we have b ones to place
    # place as many ones as needed so that a01 subsequences count decrease accordingly
    ones_left = b
    zero_count = a
    while ones_left > 0:
        while a01 >= zero_count:
            i += 1
            a01 -= zero_count
        ans[i] = '1'
        i += 1
        ones_left -= 1
    return ''.join(ans)

