def to_mask(num_str):
    # Convert a number string to a parity mask of length 18 bits
    # Pad with zeros to length 18 (left-padding)
    num_str = num_str.rjust(18, '0')
    mask = 0
    for i in range(18):
        digit = int(num_str[17 - i])  # from right to left
        if digit % 2 == 1:
            mask |= (1 << i)
    return mask

def pattern_to_mask(s):
    # Convert pattern string to mask (0 for even, 1 for odd)
    # Pad with zeros to length 18 from left
    s = s.rjust(18, '0')
    mask = 0
    for i in range(18):
        if s[17 - i] == '1':
            mask |= (1 << i)
    return mask

