    # Frequency array for letters A-Z
    freq = [0] * alpha

    # Count initial window of size 26
    question_count = 0
    for i in range(26):
        if s[i] == '?':
            question_count += 1
        else:
            freq[ord(s[i]) - ord('A')] += 1

    def can_form():
        # Check if we can form a valid 26-letter substring with current freq and question_count
        missing = 0
        for c in freq:
            if c > 1:
                # Can't have duplicates
                return False
            if c == 0:
                missing += 1
        return missing <= question_count

    # Try each window
    for start in range(n - 26 + 1):
        if start > 0:
            # Remove the left character of previous window
            left_char = s[start - 1]
            if left_char == '?':
                question_count -= 1
            else:
                freq[ord(left_char) - ord('A')] -= 1
            # Add the new right character for current window
            right_char = s[start + 26 -1]
            if right_char == '?':
                question_count += 1
            else:
                freq[ord(right_char) - ord('A')] += 1

        if can_form():
            # We found a valid window from start to start+25
            # Let's fill question marks in this window

