import sys
import math

def fwht(a, inverse=False):
    n = len(a)
    step = 1
    while step < n:
        for i in range(0, n, step * 2):
            for j in range(i, i + step):
                x = a[j]
                y = a[j + step]
                a[j] = x + y
                a[j + step] = x - y
        step <<= 1
    if inverse:
        for i in range(n):
            a[i] /= n

def read_floats():
    return list(map(float, sys.stdin.readline().split()))

def next_power_of_two(x):
    return 1 << (x-1).bit_length()

def main():
    n, x = sys.stdin.readline().split()
    n = int(n)
    x = int(x)
    P = list(map(float, sys.stdin.readline().split()))

    m = next_power_of_two(x+1)
    dist = [0.0]*m
    for i in range(x+1):
        dist[i] = P[i]

    fwht(dist)  # forward transform

    # raise each component to power n
    for i in range(m):
        # For probabilities, values can be negative after FWHT, pow works with floats but note:
        # Handle possible negative/complex issues carefully
        # However, inputs are real and for n up to 1e9, pow should work fine.
        # Defensive: If dist[i] == 0 and n > 0, result is 0
        val = dist[i]
        # pow with real base and int exponent, val can be negative so pow may return nan
        # To avoid this, store magnitude and sign separately and apply accordingly.
        sign = 1 if val >= 0 else -1
        val_abs = abs(val)
        pow_val_abs = val_abs ** n
        if sign == -1 and n % 2 == 1:
            dist[i] = -pow_val_abs
        else:
            dist[i] = pow_val_abs

    fwht(dist, inverse=True)  # inverse transform

    # Probability that XOR is 0 is dist[0]
    # Probability first player wins = 1 - dist[0]

    ans = 1.0 - dist[0]
    print(f"{ans:.9f}")

if __name__ == "__main__":
    main()

