def misplaced_positions(row):
    # Return list of indices where row[i] != i+1
    return [i for i, val in enumerate(row) if val != i + 1]

def can_fix_with_one_swap_per_row(matrix, n, m):
    # Checks if every row can be fixed with at most one swap i.e. no more than 2 misplaced elements
    for row in matrix:
        if len(misplaced_positions(row)) > 2:
            return False
    return True

def swap_columns_and_check(matrix, n, m, c1, c2):
    # Swap columns c1 and c2, check if all rows can be fixed with one swap per row
    swapped = [row[:] for row in matrix]
    for i in range(n):
        swapped[i][c1], swapped[i][c2] = swapped[i][c2], swapped[i][c1]
    return can_fix_with_one_swap_per_row(swapped, n, m)

def main():
    n, m = map(int, input().split())
    matrix = [list(map(int, input().split())) for _ in range(n)]

    # Quick checks for rows needing more than 4 misplaced elements -> impossible
    for row in matrix:
        if len(misplaced_positions(row)) > 4:
            print("NO")
            return

    # If all is already sorted or at most 2 misplaced in every row, answer YES
    if can_fix_with_one_swap_per_row(matrix, n, m):
        print("YES")
        return

    # Otherwise, try swapping any two columns and check again
    for c1 in range(m):
        for c2 in range(c1 + 1, m):
            if swap_columns_and_check(matrix, n, m, c1, c2):
                print("YES")
                return

    print("NO")

