    def __init__(self, string, pos):
        n = len(string)
        half_len = n // 2
        self.half_len = half_len
        # split string into two parts:
        # first half (left to right), second half (right to left)
        self.rows = [deque(string[:half_len]), deque(string[n-1:half_len-1:-1])]
        # Determine which row and column the "interest" position is in
        if pos < half_len:
            self.interest_row = 0
            self.interest_col = pos
        else:
            self.interest_row = 1
            self.interest_col = n - 1 - pos

    def shift(self):
        # Rotate the deques to simulate movement around the grid
        last_first_row = self.rows[0].pop()
        first_second_row = self.rows[1].popleft()
        self.rows[0].appendleft(first_second_row)
        self.rows[1].append(last_first_row)
        # Update interest position accordingly
        r, c = self.interest_row, self.interest_col
        if r == 0 and c == self.half_len - 1:
            self.interest_row = 1
        elif r == 1 and c == 0:
            self.interest_row = 0
        elif r == 0:
            self.interest_col += 1
        else:
            self.interest_col -= 1

    def neighbors(self):
        r, c = self.interest_row, self.interest_col
        if c == 0:
            # Left-most column
            return self.rows[r][c+1] + self.rows[(r+1) % 2][c+1] + self.rows[(r+1) % 2][c]
        elif c == self.half_len - 1:
            # Right-most column
