from collections import deque, defaultdict

def BFS(graph, source, visited):
    # Generator which yields all vertices connected to source (includes source)
    n = len(graph)
    queue = deque()
    queue.append(source)
    visited[source] = True

    while len(queue) > 0:
        u = queue.popleft()
        yield u

        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

