def can_finish(days, prep_days, X, n, m):
    last_exam_day = [-1] * (m + 1)  # 1-based index subjects

    for i in range(X):
        subject = days[i]
        if subject != 0:
            last_exam_day[subject] = i + 1  # 1-based day

    # Check if every subject has a last exam day <= X
    for subject in range(1, m + 1):
        if last_exam_day[subject] == -1:
            return False

    # Create list of (last_exam_day, subject, prep_days)
    exams = []
    for subject in range(1, m + 1):
        exams.append((last_exam_day[subject], subject, prep_days[subject - 1]))

    exams.sort(key=lambda x: x[0])  # sort by last exam day ascending

    current_day = 0
    for last_day, subject, prep_needed in exams:
        preparation_time = last_day - 1 - current_day
        if preparation_time < prep_needed:
            return False
        current_day = last_day  # Spend day last_day passing the exam

    return True

