    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if dist[i][k] + dist[k][j] < dist[i][j]:
                dist[i][j] = dist[i][k] + dist[k][j]

cycle_lengths = []
for i in range(1, n + 1):
    if dist[i][i] == INF:
        print(-1)
        sys.exit(0)
    length = dist[i][i]
    if length % 2 == 0:
        length //= 2
    cycle_lengths.append(length)

def lcm(a, b):
    return a * b // gcd(a, b)

answer = 1
for length in cycle_lengths:
    answer = lcm(answer, length)

print(answer)

