def make_dfs(G):
    vis = {i: False for i in G}
    cols = {i: [] for i in G}

    def dfs(u, color=None):
        if color is None:
            color = u
        vis[u] = True
        cols[color].append(u)
        for v in G[u]:
            if not vis[v]:
                dfs(v, color)
        return cols[color]

    return dfs, vis


def main():
    n, m, k = map(int, input().split())
    centers = list(map(int, input().split()))
    G = {i: [] for i in range(1, n+1)}
    for i in range(m):
        u, v = map(int, input().split())
        G[u].append(v)
        G[v].append(u)

    dfs, vis = make_dfs(G)
    ans = 0
    mx = 0
    for x in centers:
        l = dfs(x)
        mx = len(l) if len(l) > mx else mx
        ans += len(l) * (len(l) - 1) / 2

    size = 0
    for u in G:
        if not vis[u]:
            l = dfs(u)
            size += len(l)

    ans += size * (size - 1) / 2
    ans += mx * size
    print (int(ans - m))


