def find(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot == yroot:
        return False
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[yroot] < rank[xroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1
    return True

n, m, k = map(int, input().split())
gov_nodes = list(map(int, input().split()))

parent = [i for i in range(n + 1)]
rank = [0] * (n + 1)

edges = []
for _ in range(m):
    u, v = map(int, input().split())
    edges.append((u, v))
    union(parent, rank, u, v)

# Find component id for each node
comp_dict = {}
for i in range(1, n + 1):
    root = find(parent, i)
    if root not in comp_dict:
        comp_dict[root] = {
            'nodes': [],
            'edges': 0,
            'gov': False
        }
    comp_dict[root]['nodes'].append(i)

# Mark gov components and count edges within them
gov_set = set(gov_nodes)
for root in comp_dict:
    # Mark if gov present
    for node in comp_dict[root]['nodes']:
        if node in gov_set:
            comp_dict[root]['gov'] = True
            break
# Count edges per component
for u, v in edges:
    ru = find(parent, u)
    comp_dict[ru]['edges'] += 1

# Separate gov and non-gov components
gov_comps = []
non_gov_nodes = 0
non_gov_edges = 0
for comp in comp_dict.values():
    if comp['gov']:
        gov_comps.append(comp)
    else:
        non_gov_nodes += len(comp['nodes'])
        non_gov_edges += comp['edges']

# Find the largest gov component by size
gov_comps.sort(key=lambda x: len(x['nodes']), reverse=True)

# Add all non-gov nodes to the largest gov component
if gov_comps:
    gov_comps[0]['nodes'].extend([0]*non_gov_nodes)  # Just add count
else:
    # If no gov components (k=0?), all nodes form one component
    gov_comps.append({'nodes':[0]*n, 'edges':0, 'gov':True})

# Now calculate max edges for each gov component
def max_edges(x):
    return x*(x-1)//2

# Calculate current edges (sum of all edges)
total_current_edges = sum(comp['edges'] for comp in comp_dict.values())

# Calculate max edges after merging non-gov nodes to largest gov component
answer = 0
for i, comp in enumerate(gov_comps):
