def convert_base(base, num_str, pos=0):
    if not num_str:
        return 0
    for length in range(1, len(num_str) + 1):
        digit_str = num_str[-length:]
        # Skip if leading zero and length > 1
        if digit_str[0] == '0' and length > 1:
            continue
        digit = int(digit_str)
        if digit < base:
            return digit * (base ** pos) + convert_base(base, num_str[:-length], pos + 1)

