import sys
import re

def colnum_to_colletters(colnum):
    letters = []
    while colnum > 0:
        colnum -= 1  # Adjust because A=1 not 0
        letters.append(chr(colnum % 26 + ord('A')))
        colnum //= 26
    return ''.join(reversed(letters))

def colletters_to_colnum(letters):
    colnum = 0
    for ch in letters:
        colnum = colnum * 26 + (ord(ch) - ord('A') + 1)
    return colnum

def main():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    r1c1_pattern = re.compile(r'^R(\d+)C(\d+)$')

    for i in range(1, n+1):
        coord = input[i]
        match = r1c1_pattern.match(coord)
        if match:
            # R1C1 to Excel style
            row = int(match.group(1))
            col = int(match.group(2))
            col_letters = colnum_to_colletters(col)
            print(f"{col_letters}{row}")
        else:
            # Excel style to R1C1
            # split letters and digits
            letters = []
            digits = []
            for ch in coord:
                if ch.isalpha():
                    letters.append(ch)
                else:
                    digits.append(ch)
            col = colletters_to_colnum(''.join(letters))
            row = int(''.join(digits))
            print(f"R{row}C{col}")

if __name__ == "__main__":
    main()

