                h += 1
            lcp[rank[i]] = h
            if h > 0:
                h -= 1
    return lcp, rank

def suffix_array(s):
    s += '\0'
    n = len(s)
    sa = [0] * n

    cnt256 = [0] * 256
    for c in s:
        cnt256[ord(c)] += 1
    for i in range(1, 256):
        cnt256[i] += cnt256[i - 1]
    for i in range(n - 1, -1, -1):
        cnt256[ord(s[i])] -= 1
        sa[cnt256[ord(s[i])]] = i

    rank = 0
    ranks = [0] * n
    for i in range(1, n):
        if s[sa[i - 1]] != s[sa[i]]:
            rank += 1
        ranks[sa[i]] = rank

    k = 1
    while k < n:
        sa_new = [0] * n
        for i in range(n):
            sa_new[i] = sa[i] - k
            if sa_new[i] < 0:
                sa_new[i] += n

        cnt = [0] * (rank + 1)
        for i in range(n):
            cnt[ranks[i]] += 1
        for i in range(1, rank + 1):
            cnt[i] += cnt[i - 1]
        for i in range(n - 1, -1, -1):
            cnt[ranks[sa_new[i]]] -= 1
            sa[cnt[ranks[sa_new[i]]]] = sa_new[i]

        rank_new = [0] * n
        rank = 0
        for i in range(1, n):
            prev = sa[i - 1]
            curr = sa[i]
            if ranks[prev] != ranks[curr] or ranks[(prev + k) % n] != ranks[(curr + k) % n]:
                rank += 1
            rank_new[curr] = rank
        ranks = rank_new
        k <<= 1

    return sa[1:]

def kmp(s, p):
    pi = [0] * len(p)
    k = 0
    for i in range(1, len(p)):
        while k > 0 and p[k] != p[i]:
            k = pi[k - 1]
        if p[k] == p[i]:
            k += 1
        pi[i] = k

    k = 0
    res = []
    for i in range(len(s)):
        while k > 0 and p[k] != s[i]:
            k = pi[k - 1]
        if p[k] == s[i]:
            k += 1
        if k == len(p):
            res.append(i - len(p) + 1)
            k = pi[k - 1]
    return res

def lower_bound(a, x):
    left, right = 0, len(a)
    while left < right:
        mid = (left + right) // 2
        if a[mid] < x:
            left = mid + 1
        else:
            right = mid
    return left

s = input()
start = input()
end = input()

indStart = kmp(s, start)
indEnd = kmp(s, end)

if not indStart or not indEnd:
    print(0)
else:
    sa = suffix_array(s)
    lcp, rank = calc_lcp(s, sa)

    # Get minimal rank of suffixes starting at occurrences of start
    min_rank = min(rank[pos] for pos in indStart)

    resp = len(indEnd) - lower_bound(indEnd, sa[min_rank] + max(0, len(start) - len(end)))
    i = min_rank
    while i < len(lcp) and lcp[i] >= len(start):
        i += 1
        length_needed = max(lcp[i - 1] + 1, len(start))
        resp += len(indEnd) - lower_bound(indEnd, sa[i] + max(0, length_needed - len(end)))

    print(resp)

