def max_matching(graph, u, matchR, seen):
    for v in graph[u]:
        if not seen[v]:
            seen[v] = True
            if matchR[v] == -1 or max_matching(graph, matchR[v], matchR, seen):
                matchR[v] = u
                return True
    return False

def main():
    n, m = map(int, input().split())
    grid = [list(input()) for _ in range(n)]

    wolves = []
    pigs = []

    # Map from pig position to pig index
    pig_index = {}
    pig_id = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'P':
                pig_index[(i, j)] = pig_id
                pigs.append((i, j))
                pig_id += 1

    # For each wolf, list adjacent pig indices
    graph = []

    # Directions: up, down, left, right
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'W':
                edges = []
                for dx, dy in directions:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 'P':
                        edges.append(pig_index[(nx, ny)])
                graph.append(edges)

    # Max bipartite matching: left set = wolves, right set = pigs
    matchR = [-1] * pig_id
    result = 0
    for u in range(len(graph)):
        seen = [False] * pig_id
        if max_matching(graph, u, matchR, seen):
            result += 1

    print(result)

if __name__ == "__main__":
    main()

