# ending with p consecutive footmen (1 <= p <= k1)
dp_footman = [[[0]*(k1+1) for _ in range(n2+1)] for __ in range(n1+1)]

# dp_horseman[i][j][q] = number of ways to arrange i footmen, j horsemen,
# ending with q consecutive horsemen (1 <= q <= k2)
dp_horseman = [[[0]*(k2+1) for _ in range(n2+1)] for __ in range(n1+1)]

# Base cases:
# First soldier can be footman or horseman
if n1 > 0:
    dp_footman[1][0][1] = 1
if n2 > 0:
    dp_horseman[0][1][1] = 1

for i in range(n1+1):
    for j in range(n2+1):
        # Footmen endings
        for p in range(1, k1+1):
            ways = dp_footman[i][j][p]
            if ways == 0:
                continue
            # Add footman if not exceeding k1
            if i < n1 and p < k1:
                dp_footman[i+1][j][p+1] = (dp_footman[i+1][j][p+1] + ways) % MOD
            # Add horseman (start new consecutive horseman count=1)
            if j < n2:
                dp_horseman[i][j+1][1] = (dp_horseman[i][j+1][1] + ways) % MOD

        # Horsemen endings
        for q in range(1, k2+1):
            ways = dp_horseman[i][j][q]
            if ways == 0:
