def to_ternary(n):
    if n == 0:
        return '0'
    digits = []
    while n > 0:
        digits.append(str(n % 3))
        n //=3
    return ''.join(digits[::-1])

def tor(x, y):
    x_tern = to_ternary(x)
    y_tern = to_ternary(y)
    max_len = max(len(x_tern), len(y_tern))
    x_tern = x_tern.zfill(max_len)
    y_tern = y_tern.zfill(max_len)
    res_digits = [(int(a) + int(b)) % 3 for a,b in zip(x_tern, y_tern)]
    res_str = ''.join(str(d) for d in res_digits)
    return int(res_str, 3)

