def is_rectangle(segments):
    points = []
    for x1, y1, x2, y2 in segments:
        # Check if segment is horizontal or vertical
        if x1 != x2 and y1 != y2:
            return False

        points.append((x1, y1))
        points.append((x2, y2))

    # Get unique points
    unique_points = list(set(points))
    if len(unique_points) != 4:
        return False

    xs = {p[0] for p in unique_points}
    ys = {p[1] for p in unique_points}

    # There must be exactly two distinct x and y values
    if len(xs) != 2 or len(ys) != 2:
        return False

    x_min, x_max = min(xs), max(xs)
    y_min, y_max = min(ys), max(ys)

    # The 4 corners of the rectangle
    corners = {
        (x_min, y_min),
        (x_min, y_max),
        (x_max, y_min),
        (x_max, y_max)
    }

    # Check if all corners present
    if set(unique_points) != corners:
        return False

    # Build a set of edges (segments) that should be in rectangle
    expected_edges = {
        ((x_min, y_min), (x_min, y_max)),
        ((x_min, y_max), (x_max, y_max)),
        ((x_max, y_max), (x_max, y_min)),
        ((x_max, y_min), (x_min, y_min))
    }

    # Normalize edges (order points so smaller coordinate tuple goes first)
    def normalize_edge(p1, p2):
        return (p1, p2) if p1 < p2 else (p2, p1)

    normalized_expected_edges = {normalize_edge(*e) for e in expected_edges}

    normalized_given_edges = set()
    for x1, y1, x2, y2 in segments:
        normalized_given_edges.add(normalize_edge((x1,y1),(x2,y2)))

    # Check if given edges match the expected edges
    if normalized_given_edges != normalized_expected_edges:
        return False

    # Check positive area
    if x_min == x_max or y_min == y_max:
        return False

    return True

