import math

def does_fit(n, R, r):
    if r > R:
        return "NO"
    if n == 1:
        # One plate can be placed if its radius <= table radius
        return "YES" if r <= R else "NO"
    if r * 2 > R * 2:
        # For multiple plates, check if they can be placed tangent to the edge and each other
        if R - r <= 0:
            return "NO"
    # Calculate angle between centers of adjacent plates
    # sin(theta/2) = r / (R - r)
    # If r > R - r -> no solution since arcsin argument > 1
    if r > R - r:
        return "NO"
    angle = 2 * math.asin(r / (R - r))
    max_plates = int(math.floor(2 * math.pi / angle))
    return "YES" if max_plates >= n else "NO"

if __name__ == '__main__':
    n, R, r = map(int, input().split())
    print(does_fit(n, R, r))

