def format_financial_number(s):
    negative = s.startswith('-')
    if negative:
        s = s[1:]

    # Separate integer and fractional parts
    if '.' in s:
        integer_part, frac_part = s.split('.', 1)
    else:
        integer_part, frac_part = s, ''

    # Format fractional part to 2 digits
    if len(frac_part) == 0:
        frac_part = '00'
    elif len(frac_part) < 2:
        frac_part = frac_part.ljust(2, '0')
    else:
        frac_part = frac_part[:2]

    # Format integer part with commas
    # Reverse string to insert commas every 3 digits
    rev_int = integer_part[::-1]
    chunks = [rev_int[i:i+3] for i in range(0, len(rev_int), 3)]
    int_with_commas = ','.join(chunks)[::-1]

    # Construct the result string
    result = f"{int_with_commas}.{frac_part}"
    if negative:
        return f"(${result})"
    else:
        return f"${result}"

if __name__ == "__main__":
    s = input().strip()
    print(format_financial_number(s))

