def sieve_spf(n):
    spf = [0]*(n+1)
    spf[1] = 1
    for i in range(2, n+1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i*i, n+1, i):
                if spf[j] == 0:
                    spf[j] = i
    return spf

def get_prime_factors(x, spf):
    factors = set()
    while x > 1:
        factors.add(spf[x])
        x //= spf[x]
    return factors

