    import sys
    input = sys.stdin.readline

    n = int(input())
    t = list(map(int, input().split()))

    # Function to find all divisors of n
    def divisors(n):
        divs = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
            i += 1
        return divs

    divs = divisors(n)

    max_sum = max(sum(t), max(t))  # at least sum of all or max single element to cover edge cases

    # For each divisor d, the polygon size is m = n // d
    # We want m >= 3
    for d in divs:
        m = n // d
        if m >= 3:
            # For each possible starting point i in [0, d-1],
            # sum the t values at i, i+d, i+2d, ..., i+(m-1)*d
            for start in range(d):
                s = 0
                for k in range(m):
                    idx = (start + k * d) % n
                    s += t[idx]
                if s > max_sum:
                    max_sum = s

    print(max_sum)

