    components = []

    def dfs(u, comp):
        visited[u] = True
        comp.append(u)
        for w in friends[u]:
            if not visited[w]:
                dfs(w, comp)

    for i in range(1, n+1):
        if not visited[i]:
            comp = []
            dfs(i, comp)
            components.append(comp)

    # Convert each component to a set for quick lookup
    comp_sets = [set(c) for c in components]

