import sys
sys.setrecursionlimit(10**7)

def max_game_sum(n, memo):
    if n == 1:
        return 1
    if n in memo:
        return memo[n]

    max_sum = 1  # Worst case if no factor found, this path cannot proceed, but since n>1, there must be at least one factor >1 (except for prime)
    found_factor = False

    # Find divisors d such that 1 < d < n and n = a*d
    # For each such d (row length), next state is d
    limit = int(n**0.5)
    for i in range(2, limit + 1):
        if n % i == 0:
            # i is a divisor
            d = i
            if d < n:
                found_factor = True
                candidate = n + max_game_sum(d, memo)
                if candidate > max_sum:
                    max_sum = candidate

            # n//i is another divisor
            d2 = n // i
            if d2 != d and d2 < n and d2 > 1:
                found_factor = True
                candidate = n + max_game_sum(d2, memo)
                if candidate > max_sum:
                    max_sum = candidate

    # If no factor found, it means n is prime; then next step must be 1 (arrange in n rows of 1 pebble)
    if not found_factor:
        max_sum = n + max_game_sum(1, memo)

    memo[n] = max_sum
    return max_sum

def main():
    n = int(input())
    memo = {}
    print(max_game_sum(n, memo))

