def max_sum(n):
    from functools import lru_cache
    import math

    @lru_cache(None)
    def dfs(x):
        if x == 1:
            return 1
        max_next = 0
        limit = int(math.isqrt(x))
        for d in range(2, limit + 1):
            if x % d == 0:
                # d is a factor
                max_next = max(max_next, dfs(d), dfs(x // d))
        if max_next == 0:
            # x is prime, end game next step with 1
            return x + 1
        return x + max_next

    return dfs(n)


