Y = {0}

for i in range(n-1, -1, -1):
    possible_moves = move_map[moves[i]]
    possible_dx = set()
    possible_dy = set()
    for mv in possible_moves:
        dx, dy = dir_vectors[mv]
        # Backward step: previous_pos = current_pos - (dx, dy)
        # So we add (-dx, -dy) to current_pos to get previous_pos
        possible_dx.add(-dx)
        possible_dy.add(-dy)
    new_X = set()
    new_Y = set()
    for x in X:
        for dx in possible_dx:
            new_X.add(x + dx)
    for y in Y:
