def can_walk(day, a):
    n = len(a)
    if day > a[0] or day > a[-1]:
        return False
    visited = [False] * n
    visited[0] = True
    queue = [0]
    while queue:
        i = queue.pop(0)
        if i == n - 1:
            return True
        for ni in (i + 1, i + 2):
            if ni < n and not visited[ni] and a[ni] >= day:
                visited[ni] = True
                queue.append(ni)
    return False

