def max_sharpness(n):
    m = (n + 1) // 2  # center index
    # We'll assign each cell in m x m to be black or white in checkerboard:
    # black if (i+j) % 2 == 0 else white

    black_cells = []
    for i in range(m):
        for j in range(m):
            if (i + j) % 2 == 0:
                black_cells.append((i, j))

    sharpness = 0
    for (i, j) in black_cells:
        # Positions in full matrix:
        # count multiplier depends on position:
        # if (i == m-1) and (j == m-1): center cell => multiplier = 1
        # elif i == m-1 or j == m-1: middle row or col => multiplier = 2
        # else => multiplier = 4
        if i == m - 1 and j == m - 1:  # center cell
            sharpness += 1
        elif i == m - 1 or j == m - 1:
            sharpness += 2
        else:
            sharpness += 4

    return sharpness

