def find(parents, x):
    while parents[x] != x:
        parents[x] = parents[parents[x]]
        x = parents[x]
    return x

def union(parents, rank, a, b):
    a = find(parents, a)
    b = find(parents, b)
    if a != b:
        if rank[a] < rank[b]:
            parents[a] = b
        elif rank[b] < rank[a]:
            parents[b] = a
        else:
            parents[b] = a
            rank[a] += 1

