def undoubtedly_lucky(n):
    results = set()

    digits = [str(d) for d in range(10)]

    # Generate all combinations of digits x, y (x and y could be the same)
    for x in range(10):
        for y in range(x, 10):  # to avoid duplicate pairs since (x,y) == (y,x)
            # For each length from 1 to max length of n
            for length in range(1, len(str(n)) + 1):
                # Generate all numbers of length "length" with digits x and y
                # There are 2^length combinations since each position can be x or y
                # We can generate all bit masks from 0 to 2^length - 1, each bit deciding which digit to use
                limit = 1 << length
                for mask in range(limit):
                    num_digits = []
                    for pos in range(length):
                        if (mask & (1 << pos)) == 0:
                            num_digits.append(str(x))
                        else:
                            num_digits.append(str(y))
                    # The digits are generated in reverse order because pos=0 is least significant bit
                    num = int(''.join(num_digits[::-1]))
                    # Skip numbers with leading zero (if length > 1 and first digit is zero)
                    if len(str(num)) == length and num != 0:
                        if num <= n:
                            results.add(num)

    return len(results)

