def dfs(n, pos):
    # Base value: 1 if n=1 else large to find minimum
    val = 1 if n == 1 else 10**18
    for i in range(2, n + 1):
        if n % i == 0:
            # Recursively find minimal number with n//i divisors at next prime
            candidate = primes[pos]**(i - 1) * dfs(n // i, pos + 1)
            if candidate < val:
                val = candidate
    return val

