def main():
    n = int(input())
    perm = list(map(int, input().split()))
    d = list(map(int, input().split()))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        left = i - d[i]
        right = i + d[i]
        if 0 <= left < n:
            adj[i].append(left)
        if 0 <= right < n:
            adj[i].append(right)

    visited = [False] * n

    def dfs(start):
        stack = [start]
        comp = []
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return comp

    for i in range(n):
        if not visited[i]:
            comp = dfs(i)
            # initial values in this component:
            initial_vals = sorted([x + 1 for x in comp])
            target_vals = sorted([perm[x] for x in comp])
            if initial_vals != target_vals:
                print("NO")
                return
    print("YES")

if __name__ == "__main__":
    main()

