def nearest_fraction(x, y, n):
    best_a = 0
    best_b = 1
    best_diff = abs(x / y - 0)  # Starting with 0/1

    for b in range(1, n + 1):
        # Possible numerators near the target value
        a_floor = (x * b) // y
        candidates = [a_floor]
        # Add a_floor + 1 if it's a valid numerator (positive integral)
        if a_floor + 1 <= 10**10:  # large enough safe upper bound for a
            candidates.append(a_floor + 1)

        for a in candidates:
            if a < 0:
                continue
            diff = abs(x / y - a / b)
            if diff < best_diff:
                best_diff = diff
                best_a = a
                best_b = b
            elif diff == best_diff:
                if b < best_b:
                    best_a = a
                    best_b = b
                elif b == best_b and a < best_a:
                    best_a = a
                    best_b = b

    return f"{best_a}/{best_b}"

if __name__ == "__main__":
    x, y, n = map(int, input().split())
    print(nearest_fraction(x, y, n))

