def prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.add(n)
    return factors

def is_primitive_root(g, p, factors):
    for q in factors:
        if pow(g, (p - 1) // q, p) == 1:
            return False
    return True

p = int(input())
factors = prime_factors(p - 1)
count = 0
