MOD = 10**9 + 7

def modinv(a, m=MOD):
    return pow(a, m-2, m)

def precompute_factorials(n, MOD):
    fact = [1]*(n+1)
    inv_fact = [1]*(n+1)
    for i in range(2, n+1):
        fact[i] = fact[i-1]*i % MOD
    inv_fact[n] = modinv(fact[n], MOD)
    for i in range(n-1, 0, -1):
        inv_fact[i] = inv_fact[i+1]*(i+1) % MOD
    return fact, inv_fact

def nCr(n, r, fact, inv_fact):
    if r > n or r < 0:
        return 0
    return fact[n]*inv_fact[r]%MOD*inv_fact[n-r]%MOD

def solve():
    n, k = map(int, input().split())
    fact, inv_fact = precompute_factorials(k, MOD)

    # Compute sum over len
    total = 0
    for length in range(1, k+1):
        comb = nCr(k-1, length-1, fact, inv_fact)       # choose cycle nodes other than 1
        perm_cycle = fact[length -1]                      # (length-1)!
        power_term = pow(k, k-length, MOD)                # k^(k-length)
        total += comb * perm_cycle % MOD * power_term % MOD
        total %= MOD

    # (n-k)^(n-k), handle 0^0 = 1 if n=k
    outside = 1
    if n > k:
        outside = pow(n-k, n-k, MOD)

    result = (total * outside) % MOD
    print(result)

if __name__ == "__main__":
    solve()

