def ip_to_int(ip):
    parts = list(map(int, ip.split('.')))
    val = 0
    for p in parts:
        val = (val << 8) | p
    return val

def int_to_ip(val):
    parts = []
    for i in range(4):
        parts.append(str((val >> (24 - 8*i)) & 0xFF))
    return '.'.join(parts)

def mask_from_prefix_len(x):
    # x in [1..31]
    # mask with x ones left-aligned: first x bits one, rest zero
    # e.g. x=24: mask = (1 << 24) -1 shifted to left 8: (0xFFFFFF00)
    # Actually: mask = ((1 << x) - 1) << (32 - x)
    return ((1 << x) - 1) << (32 - x)

