def pos_to_coords(pos):
    col = ord(pos[0]) - ord('a') + 1
    row = int(pos[1])
    return (col, row)

def move_king(s, t):
    x1, y1 = pos_to_coords(s)
    x2, y2 = pos_to_coords(t)

    moves = []

    while (x1, y1) != (x2, y2):
        move = ""
        if y2 > y1:
            move += "U"
            y1 += 1
        elif y2 < y1:
            move += "D"
            y1 -= 1

        if x2 > x1:
            move = "R" + move if move == "" else move + "R"
            x1 += 1
        elif x2 < x1:
            move = "L" + move if move == "" else move + "L"
            x1 -= 1

        # Normalize move strings to match problem output:
        # If both directions present, order should be L/R + U/D (e.g. LU, LD, RU, RD)
        # So if move has two chars but order is reversed (e.g. UL), reorder.
        if len(move) == 2:
            # First char should be L or R, second U or D
            if move[0] in "UD" and move[1] in "LR":
                move = move[1] + move[0]

        moves.append(move)

    print(len(moves))
    for m in moves:
        print(m)


