    s = input().strip()
    n = len(s)

    from functools import lru_cache

    # Check if a substring contains only lowercase letters, and is non-empty
    def is_valid_name(sub):
        return len(sub) > 0 and all(c.isalpha() for c in sub)

    @lru_cache(None)
    def dfs(i):
        if i == n:
            return []
        # Try to find an '@' somewhere ahead
        for at_pos in range(i+1, n):
            if s[at_pos] == '@':
                A = s[i:at_pos]
                if not is_valid_name(A):
                    continue
                # Now, try to assign B (domain part), of length at least 1
