def pos_to_coords(pos):
    return ord(pos[0]) - ord('a'), int(pos[1]) - 1

def rook_attacks(rk_pos):
    rk_x, rk_y = rk_pos
    attacked = set()
    # All squares in same row and column except the rook's own position
    for i in range(8):
        if i != rk_x:
            attacked.add((i, rk_y))
        if i != rk_y:
            attacked.add((rk_x, i))
    return attacked

def knight_moves(pos):
    x, y = pos
    moves = [(x+2,y+1),(x+2,y-1),(x-2,y+1),(x-2,y-1),
             (x+1,y+2),(x+1,y-2),(x-1,y+2),(x-1,y-2)]
    return set((nx, ny) for nx, ny in moves if 0 <= nx < 8 and 0 <= ny < 8)

def main():
    rook_pos = input().strip()
    knight_pos = input().strip()
    rk = pos_to_coords(rook_pos)
    kn = pos_to_coords(knight_pos)

    # Squares attacked by rook
    rook_attacked = rook_attacks(rk)

    # Squares attacked by knight
    knight_attacked = knight_moves(kn)

    occupied = {rk, kn}

    count = 0

    # Iterate over all positions on the board
    for x in range(8):
        for y in range(8):
            pos = (x, y)
            # Position must be empty
            if pos in occupied:
                continue

            # The new knight cannot be attacked by rook or initial knight
            if pos in rook_attacked:
                continue
            if pos in knight_attacked:
                continue

            # The new knight cannot attack rook or initial knight
            new_knight_attacks = knight_moves(pos)
            if rk in new_knight_attacks:
                continue
            if kn in new_knight_attacks:
                continue

            # No attacks between new knight and others, so this square is valid
            count += 1

    print(count)

if __name__ == "__main__":
    main()

