def pos_to_coord(pos):
    col = ord(pos[0]) - ord('a')
    row = int(pos[1]) - 1
    return (row, col)

def on_board(r, c):
    return 0 <= r < 8 and 0 <= c < 8

def squares_adjacent(r1, c1, r2, c2):
    return max(abs(r1-r2), abs(c1-c2)) == 1

def rook_attacks(rook_r, rook_c, target_r, target_c, blockers):
    # Check same row or column
    if rook_r == target_r:
        # Check columns between rook_c and target_c are free
        step = 1 if rook_c < target_c else -1
        for c in range(rook_c + step, target_c, step):
            if (rook_r, c) in blockers:
                return False
        return True
    elif rook_c == target_c:
        step = 1 if rook_r < target_r else -1
        for r in range(rook_r + step, target_r, step):
            if (r, rook_c) in blockers:
                return False
        return True
    return False

def is_attacked_by_rooks(pos_r, pos_c, rooks, blockers):
    for (rr, rc) in rooks:
        if rook_attacks(rr, rc, pos_r, pos_c, blockers):
            return True
    return False

def is_attacked_by_white_king(pos_r, pos_c, wk_r, wk_c):
    return squares_adjacent(pos_r, pos_c, wk_r, wk_c)

def main():
    r1_pos, r2_pos, wk_pos, bk_pos = input().split()
    r1 = pos_to_coord(r1_pos)
    r2 = pos_to_coord(r2_pos)
    wk = pos_to_coord(wk_pos)
    bk = pos_to_coord(bk_pos)

