    # Convert input like 'a1' to Position(r, c)
    # rank (row): '1' to '8' -> 0 to 7
    # file (col): 'a' to 'h' -> 0 to 7
    return Position(int(s[1]) - 1, ord(s[0]) - ord('a'))

class Position:
    def __init__(self, r, c):
        self.r = r
        self.c = c

def king_attacks(attacker, defender):
    for dr in range(-1, 2):
        r = attacker.r + dr
        for dc in range(-1, 2):
            c = attacker.c + dc
            if r == defender.r and c == defender.c:
                return True
    return False

def rook_attacks(attacker, defender, blockers=[]):
    if attacker.r == defender.r:
        # Check horizontal line
        min_c = min(attacker.c, defender.c)
        max_c = max(attacker.c, defender.c)
        for blocker in blockers:
            if blocker.r == attacker.r and min_c < blocker.c < max_c:
                return False
        return True
    if attacker.c == defender.c:
        # Check vertical line
        min_r = min(attacker.r, defender.r)
        max_r = max(attacker.r, defender.r)
        for blocker in blockers:
            if blocker.c == attacker.c and min_r < blocker.r < max_r:
                return False
        return True
    return False

def attacked_by_white(pos, rook_a, rook_b, king_white):
