def min_trees_to_chop(n, m, garden, a, b):
    # Prefix sums (1-based indexing for convenience)
    prefix = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            prefix[i][j] = garden[i-1][j-1] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1]

    def get_sum(x1, y1, x2, y2):
        return prefix[x2][y2] - prefix[x1-1][y2] - prefix[x2][y1-1] + prefix[x1-1][y1-1]

    res = float('inf')

    # Check sub-rectangles with size a x b
    if a <= n and b <= m:
        for i in range(1, n - a + 2):
            for j in range(1, m - b + 2):
                curr = get_sum(i, j, i + a - 1, j + b - 1)
                if curr < res:
                    res = curr

    # Check sub-rectangles with size b x a if different and fits
    if b != a and b <= n and a <= m:
        for i in range(1, n - b + 2):
            for j in range(1, m - a + 2):
                curr = get_sum(i, j, i + b - 1, j + a - 1)
                if curr < res:
                    res = curr

    return res

