    import sys
    sys.setrecursionlimit(10**7)

    n, m = map(int, sys.stdin.readline().split())
    total = n * m

    odds = [i for i in range(1, total + 1) if i % 2 == 1]
    evens = [i for i in range(1, total + 1) if i % 2 == 0]

    # Count parity cells
    parity0_cells = []
    parity1_cells = []
    for i in range(n):
        for j in range(m):
            if (i + j) % 2 == 0:
                parity0_cells.append((i, j))
            else:
                parity1_cells.append((i, j))

    def try_assign(odd_to_parity0):
        grid = [[0]*m for _ in range(n)]

        if odd_to_parity0:
            # assign odd numbers to parity0 cells
            if len(parity0_cells) != len(odds) or len(parity1_cells) != len(evens):
                return None
            # assign
            for idx, (x,y) in enumerate(parity0_cells):
                grid[x][y] = odds[idx]
            for idx, (x,y) in enumerate(parity1_cells):
                grid[x][y] = evens[idx]
        else:
            # assign odd numbers to parity1 cells
            if len(parity1_cells) != len(odds) or len(parity0_cells) != len(evens):
                return None
            for idx, (x,y) in enumerate(parity1_cells):
                grid[x][y] = odds[idx]
            for idx, (x,y) in enumerate(parity0_cells):
                grid[x][y] = evens[idx]
        # Check adjacency condition
        for i in range(n):
            for j in range(m):
                for ni,nj in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)]:
                    if 0 <= ni < n and 0 <= nj < m:
                        if abs(grid[i][j] - grid[ni][nj]) <=1:
                            return None
        return grid

