#!/usr/bin/env python3

def main():
    lines = []
    try:
        while True:
            lines.append(input())
    except EOFError:
        pass

    width = max(map(len, lines))
    stars = "*" * (width + 2)
    space = " " * width

    print(stars)
    left = True  # flag to alternate extra space placement when fill is odd

    for line in lines:
        fill = width - len(line)
        center = ["*"]

        if fill == 0:
            # line perfectly fits the width
            center.append(line)
        elif fill == width:
            # empty line, print all spaces
            center.append(space)
        else:
            left_spaces = space[:fill // 2]
            right_spaces = space[:fill // 2]

            if fill % 2 == 1:
                # odd fill, alternate extra space
                if left:
                    center += [left_spaces, line, right_spaces, " "]
                else:
                    center += [" ", left_spaces, line, right_spaces]
                left = not left
            else:
                # even fill, split evenly
                center += [left_spaces, line, right_spaces]

        center.append("*")
        print("".join(center))

    print(stars)


if __name__ == "__main__":
    main()

