def main():
    n = int(input())
    heights = tuple(map(int, input().split()))
    pairs = 0

    # Find the highest hill and its index
    highest_height, start_idx = max((h, i) for i, h in enumerate(heights))

    stack = []
    last = highest_height
    count = 0

    def push(x):
        stack.append(x)

    def pop():
        return stack.pop()

    # Iterate counter-clockwise from the highest hill (with wrap-around)
    for i in range(start_idx - 1, start_idx - n, -1):
        current = heights[i % n]

        while current > last:
            pairs += count
            last, count = pop()

        if current == last:
            count += 1
            pairs += count
        else:
            pairs += 1
            push((last, count))
            last = current
            count = 1

    push((last, count))

    # Sum pairs from the remaining stack except for one or two entries depending on condition
    end = len(stack)
    start = 1 if stack[0][1] else 2
    pairs += sum(stack[k][1] for k in range(start, end))

    print(pairs)


