def smallest_prime_factors(limit):
    spf = [0] * (limit + 1)
    spf[1] = 1
    for i in range(2, limit + 1):
        spf[i] = 0
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == 0:
            for j in range(i*i, limit + 1, i):
                if spf[j] == 0:
                    spf[j] = i
    for i in range(2, limit + 1):
        if spf[i] == 0:
            spf[i] = i
    return spf

def main():
