present_letters = set(ch for ch in s if ch != '?')
missing_letters = allowed_letters - present_letters

# Step 3: Insert missing letters in '?' pairs from right to left
for i in range(n // 2, -1, -1):
    j = n - 1 - i
    if len(missing_letters) == 0:
        break
    if s[i] == '?' and s[j] == '?':
        # Put max missing letter here to keep lex minimality
        letter = max(missing_letters)
        s[i] = s[j] = letter
