from itertools import combinations


def main():
    heroes = ("Anka", "Chapay", "Cleo", "Troll", "Dracul", "Snowy", "Hexadecimal")
    n = int(input())
    likes = [[False] * 7 for _ in range(7)]

    for _ in range(n):
        p, _, q = input().split()
        likes[heroes.index(p)][heroes.index(q)] = True

    a, b, c = map(int, input().split())

    team_splits = []
    # Enumerate all possible splits into three teams with sizes i, j, 7 - i - j
    for i in range(1, 6):
        for j in range(1, 7 - i):
            k = 7 - i - j
            exp_values = (a // i, b // j, c // k)
            diff = max(exp_values) - min(exp_values)
            team_splits.append((diff, i, j))

    # Find minimal experience difference
    min_diff = min(team_splits, key=lambda x: x[0])[0]

    liking_values = []

    # For all splits with minimal difference, try all team assignments
    for diff, i, j in ((d, x, y) for d, x, y in team_splits if d == min_diff):
        for team1 in combinations(range(7), i):
            remaining = [x for x in range(7) if x not in team1]
            for team2 in combinations(remaining, j):
                team3 = [x for x in remaining if x not in team2]

                total_liking = 0
                for team in (team1, team2, team3):
                    for p in team:
                        for q in team:
                            if likes[p][q]:
                                total_liking += 1
                liking_values.append(total_liking)

    print(min_diff, max(liking_values))


