import sys
import re
sys.setrecursionlimit(10**7)

# Tokenizer
TOKEN_REGEX = re.compile(r'\s*([A-Za-z]+|[0-9]+|[-+*/()]|\S)')

class Tokenizer:
    def __init__(self, s):
        self.tokens = []
        pos = 0
        while True:
            m = TOKEN_REGEX.match(s, pos)
            if not m:
                break
            token = m.group(1)
            self.tokens.append(token)
            pos = m.end()
        self.pos = 0
    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None
    def next(self):
        if self.pos < len(self.tokens):
            r = self.tokens[self.pos]
            self.pos += 1
            return r
        return None
    def expect(self, x):
        t = self.next()
        if t != x:
            raise Exception("Expected '%s' but got '%s'" % (x,t))

# Expression AST nodes
# We define 3 node types: Num, Var, BinOp, and Parens

class Expr:
    def __str__(self):
        return self.str()
    def str(self):
        raise NotImplementedError()
    def precedence(self):
        raise NotImplementedError()
    def is_left_associative(self):
        return True
    # compare ignoring spaces
    def equals_ignoring_spaces(self, other):
        return self.str().replace(' ','') == other.str().replace(' ','')
    def copy(self):
        raise NotImplementedError()

class Num(Expr):
    def __init__(self, v):
        self.v = v
    def str(self):
        return str(self.v)
    def precedence(self):
        return 100
    def copy(self):
        return Num(self.v)

class Var(Expr):
    def __init__(self, name):
        self.name = name
    def str(self):
        return self.name
    def precedence(self):
        return 100
    def copy(self):
        return Var(self.name)

class BinOp(Expr):
    # op in '+', '-', '*', '/'
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right
    def str(self):
        # Add minimal parentheses for infix string expression
        # We do not do minimal here because sometimes needed to print
        # but we will have a separate function for pretty printing with paren removal
        return ('('+self.left.str()+')' if self.left.precedence() < self.precedence() else self.left.str()) + \
               self.op + \
               ('('+self.right.str()+')' if (self.right.precedence() < self.precedence() or
                                            (self.right.precedence() == self.precedence() and self.op in ['-','/'])) else self.right.str())
    def precedence(self):
        if self.op in ('+','-'):
            return 1
        elif self.op in ('*','/'):
            return 2
        else:
            raise Exception("Unknown op %s" % self.op)
    def copy(self):
        return BinOp(self.op, self.left.copy(), self.right.copy())

class Parens(Expr):
    def __init__(self, expr):
        self.expr = expr
    def str(self):
        return '(' + self.expr.str() + ')'
    def precedence(self):
        # parentheses override precedence externally, but in comparisons we use expr precedence
        return 1000
    def copy(self):
        return Parens(self.expr.copy())

# Parser for expressions (recursive descent)
# Grammar:
# expr = term { (+|-) term }
# term = factor { (*|/) factor }
# factor = number | var | (expr)

class Parser:
    def __init__(self, s):
        self.tokenizer = Tokenizer(s)

    def parse(self):
        expr = self.parse_expr()
        if self.tokenizer.peek() is not None:
            raise Exception("Unexpected token after end")
        return expr

    def parse_expr(self):
        left = self.parse_term()
        while True:
            t = self.tokenizer.peek()
            if t in ('+','-'):
                op = self.tokenizer.next()
                right = self.parse_term()
                left = BinOp(op,left,right)
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_factor()
        while True:
            t = self.tokenizer.peek()
            if t in ('*','/'):
                op = self.tokenizer.next()
                right = self.parse_factor()
                left = BinOp(op,left,right)
            else:
                break
        return left

    def parse_factor(self):
        t = self.tokenizer.peek()
        if t is None:
            raise Exception("Unexpected end of input")
        if t == '(':
            self.tokenizer.next()
            e = self.parse_expr()
            self.tokenizer.expect(')')
            return Parens(e)
        elif t.isdigit():
            self.tokenizer.next()
            return Num(int(t))
        elif re.match(r'^[A-Za-z]+$', t):
            self.tokenizer.next()
            return Var(t)
        else:
            raise Exception("Unexpected token in factor: %s" % t)

# Macro storage: mapping macro_name -> AST (fully substituted)
#
# Substitution works by walking the AST and replacing Var nodes whose name is macro_name with its corresponding AST.
# For ordinary substitution, just replace Var by macro AST directly (deepcopy).
# For safe substitution, replace Var by Parens(macro AST copy).

def substitute_expr(expr, macros, safe):
    # recursive substitution of macros
    if isinstance(expr, Num):
        return expr.copy()
    elif isinstance(expr, Var):
        if expr.name in macros:
            sub_expr = macros[expr.name]
            sub_copy = sub_expr.copy()
            if safe:
                return Parens(sub_copy)
            else:
                return sub_copy
        else:
            return expr.copy()
    elif isinstance(expr, BinOp):
        left_sub = substitute_expr(expr.left, macros, safe)
        right_sub = substitute_expr(expr.right, macros, safe)
        return BinOp(expr.op, left_sub, right_sub)
    elif isinstance(expr, Parens):
        inner_sub = substitute_expr(expr.expr, macros, safe)
        return Parens(inner_sub)
    else:
        raise Exception("Unknown expr type in substitution")

# Parentheses removal rules:
#
# Let's implement a function that will remove parentheses where safe.
# Conditions to remove parentheses around an expression inside a BinOp:
#
# We have parent node (P) and child node (C).
# If C is Parens(X), decide whether parentheses can be removed.
# Parentheses can be removed if after removing they don't change the order of evaluation.
#
# The rules (commonly):
# For removing parentheses around X in parent P with operator:
#
# - If X is a single number or variable, parentheses can always be removed.
#
# - If P is None (top-level), parentheses can be removed.
#
# - Otherwise:
#   Let Px = parent op precedence
#   Let Cx = child op precedence
