def rotate(s, k):
    return s[k:] + s[:k]

def complement(s):
    return ''.join('1' if c == '0' else '0' for c in s)

def minimal_string(s):
    n = len(s)
    candidates = []
    # rotations of s
    for i in range(n):
        candidates.append(rotate(s, i))
    # rotations of complement(s)
    cs = complement(s)
    for i in range(n):
        candidates.append(rotate(cs, i))
    return min(candidates)

def necklace_generator(n):
    # Generate binary necklaces of length n in lex order using 
    # the "necklaces generation algorithm" from Fredricksen-Maiorana.
    # Returns generator of strings.

    a = [0] * (n + 1)

    def gen(t, p):
        if t > n:
            if n % p == 0:
                yield ''.join(str(x) for x in a[1:n + 1])
        else:
            a[t] = a[t - p]
            yield from gen(t + 1, p)
            for j in range(a[t - p] + 1, 2):
                a[t] = j
                yield from gen(t + 1, t)

    yield from gen(1, 1)


def main():
    import sys
    sys.setrecursionlimit(10 ** 7)
    n, k = sys.stdin.readline().split()
    n = int(n)
    k = int(k)

    # We'll generate necklaces in lex order
    # For each necklace s:
    #   find minimal = min(s, minimal_string(s complement rotations))
    #   if minimal == s, it's the minimal representative for the class
    #   else skip (class has smaller representative among complement rotations)
    count = 0
    for necklace in necklace_generator(n):
        # compute minimal representative for the class:
        # to avoid double counting, only output if necklace is <= all complement rotations
        cs = complement(necklace)
        # compute minimal rotation of cs
        min_comp = None
        for i in range(n):
            rotated = rotate(cs, i)
            if min_comp is None or rotated < min_comp:
                min_comp = rotated
        if necklace <= min_comp:
            # necklace is minimal representative
            count += 1
            if count == k:
                print(necklace)
                return
    print(-1)

if __name__ == "__main__":
    main()

