class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.data = [-1]*(n+1)
    def update(self, i, val):
        while i <= self.n:
            if val > self.data[i]:
                self.data[i] = val
            i += i & -i
    def query(self, i):
        res = -1
        while i > 0:
            if self.data[i] > res:
                res = self.data[i]
            i -= i & -i
        return res

