def parse_expression(expr):
    # parses expr of form &...& base *...*
    # returns (num_amps, base_name, num_stars)
    num_amps = 0
    idx = 0
    while idx < len(expr) and expr[idx] == '&':
        num_amps += 1
        idx += 1
    # now read base name
    base_start = idx
    while idx < len(expr) and expr[idx].isalpha():
        idx += 1
    base_name = expr[base_start:idx]
    num_stars = 0
    while idx < len(expr) and expr[idx] == '*':
        num_stars += 1
        idx += 1
    return num_amps, base_name, num_stars

def resolve_type(num_amps, base_name, num_stars, current_types):
    # get base type
    if base_name not in current_types:
        # undefined type => errtype
        base = 'errtype'
        ptr = 0
    else:
        base, ptr = current_types[base_name]
    # if base is errtype, operations don't change it
    if base == 'errtype':
        return ('errtype', 0)
    # apply pointer additions
    ptr += num_stars
    # apply dereferences
    for _ in range(num_amps):
        if base == 'errtype':
            break
        if ptr == 0:
            base = 'errtype'
            ptr = 0
            break
        else:
            ptr -= 1
    return (base, ptr)

for _ in range(n):
    line = input().strip()
    if line.startswith('typedef'):
        # typedef A B
        # split into ['typedef', A, B]
        _, A, B = line.split()
        num_amps, base_name, num_stars = parse_expression(A)
        t = resolve_type(num_amps, base_name, num_stars, types)
        types[B] = t
    else:
        # typeof A
        _, A = line.split()
        num_amps, base_name, num_stars = parse_expression(A)
