n = int(input())
clubs = []
for _ in range(n):
    team, hometown = input().split()
    optionA = team[:3]
    optionB = team[:2] + hometown[0]
    clubs.append((optionA, optionB))

# If optionA == optionB => only one option effectively
for i in range(n):
    if clubs[i][0] == clubs[i][1]:
        clubs[i] = (clubs[i][0], clubs[i][0])

# Status:
# assigned[i] = 'A' or 'B' or None (not assigned)
assigned = [None] * n

# To quickly find clubs by optionA name
optionA_map = {}
for i, (a, b) in enumerate(clubs):
    if a not in optionA_map:
        optionA_map[a] = []
    optionA_map[a].append(i)

# Chosen short names set for uniqueness check
chosen_short = set()

# Forbidden option A short names if any club uses option B with that option A
forbidden_optionA = set()

def try_assign():
    queue = deque()
    # Initial attempt: assign all to option A
    for i in range(n):
        assigned[i] = 'A'
    # Check duplicates in optionA assignment
    for a, lst in optionA_map.items():
        if len(lst) > 1:
            # Duplicates - enqueue all these clubs for reconsidering assignment
            for i in lst:
                queue.append(i)

    while queue:
        i = queue.popleft()
        if assigned[i] == 'B':
            # Already option B, no conflicts
            continue

        a, b = clubs[i]
        # If option B == option A => can't do anything
        if a == b:
            # No choice but option A -- conflict if duplicated
            # but already duplicated, no solution
            return False

        # Try assign option B for club i
        assigned[i] = 'B'
        forbidden_optionA.add(a)
        # Now, for all clubs j that have optionA = a and assigned to A,
        # must force them to choose optionB due to forbidden optionA a
        for j in optionA_map[a]:
            if j != i and assigned[j] == 'A':
                # Try to switch j to B
                aj, bj = clubs[j]
                if aj == bj:
                    # Can't switch because only one option possible and it's forbidden
                    return False
                assigned[j] = 'B'
                forbidden_optionA.add(aj)
                # Enqueue j for propagation to check other clubs
                queue.append(j)

    # After assigning options, check for duplicate short names
    chosen_short.clear()
    for i in range(n):
        if assigned[i] == 'A':
            short = clubs[i][0]
        else:
            short = clubs[i][1]
        if short in chosen_short:
            # Duplicate short name
            return False
        chosen_short.add(short)

    # Also check that no club assigned option A has optionA in forbidden_optionA
    for i in range(n):
        if assigned[i] == 'A' and clubs[i][0] in forbidden_optionA:
            return False

    return True

