def solve():
    n, k = map(int, input().split())
    s = input().split()

    # Function to generate distinct names given an index
    # We'll generate names like A, B, C,..., Z, Aa, Ab,..., Az, Ba,...
    def get_name(idx):
        if idx < 26:
            return chr(ord('A') + idx)
        else:
            idx -= 26
            first = chr(ord('A') + idx // 26)
            second = chr(ord('a') + idx % 26)
            return first + second

    names_idx = [0] * n

    # Assign distinct names to first k-1 soldiers
    for i in range(k - 1):
        names_idx[i] = i

    max_used = k - 2  # highest index used so far

    for i in range(k - 1, n):
        group_index = i - k + 1  # index in s list corresponding to group ending at i
        if s[group_index] == "YES":
            max_used += 1
            names_idx[i] = max_used
        else:
            # Assign same name as soldier at start of the group to ensure repetition
