def process_moves(v, moves, n):
    for m in moves:
        # Calculate position of the lowest set bit and check if v is a power of two
        bit_pos = 0
        t = v
        while (t & 1) == 0:
            t >>= 1
            bit_pos += 1
        power_of_2 = (t == 1)

        if m == 'U':
            # Move to parent
            if power_of_2:
                # v is root of some subtree: parent = v << 1
                new_v = v << 1
            else:
                # Clear the bit at bit_pos, set the bit at bit_pos+1
                new_v = (v & ~(1 << bit_pos)) | (1 << (bit_pos + 1))
        elif m == 'L':
            # Move to left child
            if power_of_2:
                # At some subtree root, left child = v >> 1
                new_v = v >> 1
            else:
                if bit_pos > 0:
                    # Clear bit_pos, set bit_pos-1
                    new_v = (v & ~(1 << bit_pos)) | (1 << (bit_pos - 1))
                else:
                    # No left child
                    new_v = 0
        else:  # m == 'R'
            # Move to right child
            if bit_pos > 0:
                new_v = v | (1 << (bit_pos - 1))
            else:
                # No right child
                new_v = 0

        if 1 <= new_v <= n:
            v = new_v
        # else: ignore this move (can't go outside the tree)

    return v


