from collections import deque

def bfs(start):
    queue = deque()
    queue.append((start, 0))
    mark[start] = True

    while queue:
        state, dist = queue.popleft()
        # If it is not the initial step and state == start, we've found answer
        if state == start and dist > 0:
            return dist

        for v in range(len(edges)):
            if edges[v]:
                next_state = state + v - OFFSET
                if 0 <= next_state < len(mark) and not mark[next_state]:
                    mark[next_state] = True
                    queue.append((next_state, dist + 1))
    return -1

