def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def k_factorization(n, k):
    factors = prime_factors(n)

    if len(factors) < k:
        print(-1)
        return

    # output first k-1 factors
    for i in range(k-1):
        print(factors[i], end=' ')

    # multiply the rest to form the last factor
    prod = 1
    for i in range(k-1, len(factors)):
        prod *= factors[i]
    print(prod)

