import sys
import math

input = sys.stdin.readline

def log_poisson_pmf(k, lam):
    # k should be >= 0
    if k < 0:
        return -math.inf
    # log Pois(k; lam) = k*log(lam) - lam - log(k!)
    return k * math.log(lam) - lam - math.lgamma(k + 1)

t = int(input())
for _ in range(t):
    n, P = map(int, input().split())
    xs = list(map(int, input().split()))

    # For poisson: probability of X_i = k is Pois(k + P; P)
    # For uniform: probability if k in [-P, P-1] is 1/(2P), else 0.
    # Range for uniform:
    low_uniform = -P
    high_uniform = P - 1
    uniform_prob = 1 / (2 * P)

    ll_poisson = 0.0
    ll_uniform = 0.0
    valid_uniform = True

    for k in xs:
        # Poisson pmf at k+P
        log_p_pois = log_poisson_pmf(k + P, P)
        if log_p_pois == -math.inf:
            # impossible under Poisson
            ll_poisson = -math.inf
        else:
            if ll_poisson != -math.inf:
                ll_poisson += log_p_pois

        # Uniform pmf
        if low_uniform <= k <= high_uniform:
            ll_uniform += math.log(uniform_prob)
        else:
            # zero probability under uniform
            valid_uniform = False

    if ll_poisson == -math.inf:
        # impossible under Poisson, must be uniform
        print("uniform")
    elif not valid_uniform:
        # impossible under uniform, must be Poisson
        print("poisson")
    else:
        # compare log likelihoods
        if ll_poisson >= ll_uniform:
            print("poisson")
        else:
            print("uniform")

