def mst_cost(nums, bit):
    if len(nums) <=1 or bit < 0:
        return 0
    left = []
    right = []
    for num in nums:
        if (num >> bit) & 1:
            right.append(num)
        else:
            left.append(num)
    if not left:
        return mst_cost(right, bit-1)
    if not right:
        return mst_cost(left, bit-1)
    return mst_cost(left, bit-1) + mst_cost(right, bit-1) + (1 << bit)

