from sys import stdout

def query(x, y):
    print(1, x, y)
    stdout.flush()
    response = input()
    return response == "TAK"

def find_first(n):
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        # Ask if minimal ordered dish is <= mid
        # query(mid, mid+1): "TAK" means minimal ordered dish <= mid
        # "NIE" means minimal ordered dish > mid
        if query(mid, mid+1):
            right = mid
        else:
            left = mid + 1
    return left

def find_second(n, first):
    # Try left side if possible
    if first > 1:
        left, right = 1, first - 1
        while left < right:
            mid = (left + right) // 2
            # If querying (mid, first) returns TAK, then closest ordered dish to mid
            # is closer than to first, meaning there is an ordered dish in [left, first-1]
            # Use query(mid, first) to check if there's a dish close to mid vs first
            if query(mid, first):
                right = mid
            else:
                left = mid + 1
        # verify if left is actually ordered dish via query
        # Since we don't know exact dishes, just accept found dish
        if query(left, first):
            return left
    # Otherwise, try right side
    if first < n:
        left, right = first + 1, n
        while left < right:
            mid = (left + right) // 2
            if query(first, mid):
                left = mid + 1
            else:
                right = mid
        # left could be beyond n or invalid, check boundary
        if left <= n:
            # We must confirm the dish at left is ordered dish
            # Double check by querying (first, left)
            if not query(first, left):
                return left
    # As per problem constraints k>=2 so second dish must exist
    # If not found by above, just pick any different dish
    if first > 1:
        return first -1
    else:
        return first + 1

def main():
    n, k = map(int, input().split())
    first = find_first(n)
    second = find_second(n, first)
    print(2, first, second)
    stdout.flush()

