def solve():
    n, m = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(n)]

    def apply_moves(matrix, rows_count, cols_count):
        row_moves = []
        col_moves = []

        # Subtract minimum in each row, record row moves
        for i in range(rows_count):
            row_min = min(matrix[i])
            if row_min > 0:
                for j in range(cols_count):
                    matrix[i][j] -= row_min
                row_moves.extend([i] * row_min)

        # For each column, values must be uniform
        for j in range(cols_count):
            col_vals = [matrix[i][j] for i in range(rows_count)]
            col_min = min(col_vals)
            col_max = max(col_vals)
            # If not all equal, no solution
            if col_max != col_min:
                return None, None
            if col_min > 0:
                col_moves.extend([j] * col_min)

        return row_moves, col_moves

    # To minimize moves, choose to operate either on rows then columns or transpose and vice versa.
    if n <= m:
        row_moves, col_moves = apply_moves([row[:] for row in grid], n, m)
        if row_moves is None:
            print(-1)
            return
        total_moves = len(row_moves) + len(col_moves)
        print(total_moves)
        for r in row_moves:
            print("row", r + 1)
        for c in col_moves:
            print("col", c + 1)
    else:
        # Transpose and switch roles
        transposed_grid = [[grid[i][j] for i in range(n)] for j in range(m)]
        row_moves, col_moves = apply_moves(transposed_grid, m, n)
        if row_moves is None:
            print(-1)
            return
        total_moves = len(row_moves) + len(col_moves)
        print(total_moves)
        # Here row_moves represent moves on columns originally, col_moves on rows originally
        for c in row_moves:
            print("col", c + 1)
        for r in col_moves:
            print("row", r + 1)

if __name__ == "__main__":
    solve()

