def main():
    import sys

    n, m = map(int, sys.stdin.readline().split())
    grid = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]

    moves = []
    nmoves = 0

    while True:
        min_in_rows = [min(row) for row in grid]
        min_in_cols = [min(grid[i][j] for i in range(n)) for j in range(m)]

        max_min_row = max(min_in_rows)
        max_min_col = max(min_in_cols)

        if max_min_row == 0 and max_min_col == 0:
            break

        # Choose based on problem logic: prefer column moves when n >= m and max_min_col > 0
        if (n >= m and max_min_col > 0) or max_min_row == 0:
            col_idx = min_in_cols.index(max_min_col)
            moves.append((max_min_col, ('col', col_idx + 1)))
            nmoves += max_min_col
            for i in range(n):
                grid[i][col_idx] -= max_min_col
        else:
            row_idx = min_in_rows.index(max_min_row)
            moves.append((max_min_row, ('row', row_idx + 1)))
            nmoves += max_min_row
            for j in range(m):
                grid[row_idx][j] -= max_min_row

    # After moves, grid should be all zeros
    if any(cell > 0 for row in grid for cell in row):
        print(-1)
        return

    print(nmoves)
    for repeat, (move_type, idx) in moves:
        for _ in range(repeat):
            print(move_type, idx)

