import sys
import bisect

def generate_primes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = False
    is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    matrix = [list(map(int, input().split())) for _ in range(n)]

    MAX_VAL = 150000  # Larger than max element + increments needed to next prime
    primes = generate_primes(MAX_VAL)

    # Precompute increments needed to reach the next prime
    increments = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            val = matrix[i][j]
            pos = bisect.bisect_left(primes, val)
            if pos < len(primes) and primes[pos] == val:
                increments[i][j] = 0
            else:
                increments[i][j] = primes[pos] - val

    min_moves = float('inf')

    # Check rows
    for i in range(n):
        row_sum = sum(increments[i])
        if row_sum < min_moves:
            min_moves = row_sum

    # Check columns
    for j in range(m):
        col_sum = sum(increments[i][j] for i in range(n))
        if col_sum < min_moves:
            min_moves = col_sum

    print(min_moves)

if __name__ == "__main__":
