                candidate_items.append(item_name)

    # For any best candidate item, assign residents accordingly and return item name
    for item_name in candidate_items:
        size = int(items[item_name][4])
        # Move top residents_sorted to this item (up to capacity)
        # For each resident to move, remove from previous item and assign to current
        for i in range(min(size, len(residents_sorted))):
            r = residents_sorted[i]
            old_item = lies_in[r[0]]
            if old_item != item_name:
                equipped_items[old_item].remove(r)
                lies_in[r[0]] = item_name
                equipped_items[item_name].append(r)
        # If after assignment equipped[item_name] exceeds capacity, evict oldest residents
        while len(equipped_items[item_name]) > size:
            to_evict = equipped_items[item_name][0]
            # Try to find an item with free slot to move evicted resident
            moved = False
            for other_item, params in items.items():
                if len(equipped_items[other_item]) < int(params[4]):
                    lies_in[to_evict[0]] = other_item
                    equipped_items[other_item].append(to_evict)
                    moved = True
                    break
            equipped_items[item_name].pop(0)
        return item_name
    return None

def main():
    n = int(input())
    items = {}
    equipped_items = {}
    for _ in range(n):
        t = tuple(input().split())
        items[t[0]] = t[1:]
        equipped_items[t[0]] = []

    k = int(input())
    residents = [None] * k
    lies_in = {}
    for i in range(k):
        t = tuple(input().split())  # name, type, bonus, home
        residents[i] = t
        equipped_items[t[3]].append(t)
        lies_in[t[0]] = t[3]

    can_move = any(len(equipped_items[name]) < int(params[4]) for name, params in items.items())

    if can_move:
        glads = sorted([r for r in residents if r[1] == 'gladiator'], key=lambda x: -int(x[2]))
        sentries = sorted([r for r in residents if r[1] == 'sentry'], key=lambda x: -int(x[2]))
        physicians = sorted([r for r in residents if r[1] == 'physician'], key=lambda x: -int(x[2]))

        weapon = search_for('weapon', 1, glads, equipped_items, items, lies_in)
        armor = search_for('armor', 2, sentries, equipped_items, items, lies_in)
        orb = search_for('orb', 3, physicians, equipped_items, items, lies_in)

        # After assignment, ensure no item is overloaded by moving residents if needed
        for itm in [weapon, armor, orb]:
            size = int(items[itm][4])
            while len(equipped_items[itm]) > size:
                to_move = equipped_items[itm][0]
                for other_name, params in items.items():
                    if len(equipped_items[other_name]) < int(params[4]):
                        equipped_items[other_name].append(to_move)
                        lies_in[to_move[0]] = other_name
                        break
                equipped_items[itm].pop(0)

        print_item(weapon, equipped_items)
        print_item(armor, equipped_items)
        print_item(orb, equipped_items)
    else:
        weapon = search_best('weapon', 1, 'gladiator', equipped_items, items)
        armor = search_best('armor', 2, 'sentry', equipped_items, items)
        orb = search_best('orb', 3, 'physician', equipped_items, items)

        print_item(weapon, equipped_items)
        print_item(armor, equipped_items)
        print_item(orb, equipped_items)

if __name__ == '__main__':
    main()
